SELECT CASE WHEN COUNT(1) > 0 THEN 'Y' ELSE 'N' END AS EXISTS_YN
  FROM member
 WHERE login_id = #{loginId}

SELECT CASE WHEN COUNT(1) > 0 THEN 'Y' ELSE 'N' END AS EXISTS_YN
  FROM member
 WHERE email = #{email}

SELECT id, login_id, name, role, status
  FROM member
 WHERE login_id = #{loginId}
   AND password = #{password}
   AND status = 'ACTIVE'
